%   returns o: real[1][3] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    o = zeros(3, 1);
    g = u.g;
    [t__585, t__586] = asils.models.gyrobias.gyro_bias_walk(u.brw, d.rrw, dt, g);
    brw = t__585;
