    [t__587, t__588] = asils.pc.stream_normal3(g);
    n2 = t__587;
    g = t__588;
    u.g = g;
    mw = [u.m(1, 1)*w(1) + u.m(1, 2)*w(2) + u.m(1, 3)*w(3); u.m(2, 1)*w(1) + u.m(2, 2)*w(2) + u.m(2, 3)*w(3); u.m(3, 1)*w(1) + u.m(3, 2)*w(2) + u.m(3, 3)*w(3)];
    o = [0; 0; 0];
