        o((i) + 1) = asils.models.coilsat.act_clamp((((mw((i) + 1) + u.b((i) + 1)) + u.brw((i) + 1)) + ((d.arw / h__708) * n2((i) + 1))), (-(d.range)), d.range);
    end
end
